#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "material_aid_codec_archive.hpp"
#include "material_aid_internal.hpp"
namespace hanmo::resident {
namespace {
using namespace aid_detail;
void source_shape(const MomentOwnerSource&r){if(!valid_source_ref(r.source_ref)||r.source_schema<1)fail("MaterialAidActualSourceShapeMismatch",r.source_ref.id);}
void leg_shape(const AidSourceLegRef&r){source_shape(r.source);if(r.leg_ordinal<0)fail("MaterialAidActualLegOrdinalRequired",r.source.source_ref.id);}
void unit_shape(const BudgetUnit&u){if(const auto*i=std::get_if<BudgetItemQuantity>(&u);i&&i->item_id.empty())fail("MaterialAidItemMeasureRequired");}
template<class T>void table_shape(const OrderedTable<T>&table){if(table.rows().size()>CodecVisitor::max_items)fail("CheckpointCollectionTooLarge");for(const auto&r:table.rows())if(r.first.empty()||r.first!=r.second.id)fail("MaterialAidRecordKeyMismatch",r.first);}
void strings(const std::vector<StableId>&refs){if(refs.size()>CodecVisitor::max_items)fail("CheckpointCollectionTooLarge");for(std::size_t i=0;i<refs.size();++i){if(refs[i].empty())fail("MaterialAidOriginalReferenceRequired");for(std::size_t j=0;j<i;++j)if(refs[j]==refs[i])fail("DuplicateMaterialAidOriginalReference",refs[i]);}}
}
Status validate_treaty_material_aid_shape(const TreatyMaterialAidState&s){try{
 if(s.schema_version!=1)fail("UnsupportedTreatyMaterialAidVersion");
 table_shape(s.schedule_commitments);table_shape(s.occurrence_cap_reservations);table_shape(s.establishments);table_shape(s.obligations);table_shape(s.resource_issues);table_shape(s.receipts);table_shape(s.schedule_releases);table_shape(s.deadline_results);
 for(const auto&r:s.schedule_commitments.rows()){const auto&v=r.second;if(v.schedule_id.empty()||!valid_source_ref(v.treaty_term_ref)||v.authority_refs.empty()||(v.termination_source_ref&&!valid_source_ref(*v.termination_source_ref)))fail("InvalidAidScheduleCommitment",v.id);source_shape(v.resource_acceptance_ref);take(encode_world_moment(v.accepted_at));for(const auto&a:v.authority_refs)source_shape(a);strings(v.occurrence_cap_reservation_refs);strings(v.budget_binding_refs);for(const auto&a:v.established_occurrence_refs)if(!same_source_ref(a,material_aid_establishment_source(a.id)))fail("InvalidAidEstablishmentReference",v.id);}
 for(const auto&r:s.occurrence_cap_reservations.rows()){const auto&v=r.second;if(v.schedule_commitment_id.empty()||v.occurrence_ordinal<0||v.quantity<=0||(v.establishment_result_ref&&v.release_result_ref))fail("InvalidAidOccurrenceCap",v.id);unit_shape(v.unit);if(v.establishment_result_ref&&!same_source_ref(*v.establishment_result_ref,material_aid_establishment_source(v.establishment_result_ref->id)))fail("InvalidAidConversionReference",v.id);if(v.release_result_ref&&!same_source_ref(*v.release_result_ref,material_aid_schedule_release_source(v.release_result_ref->id)))fail("InvalidAidReleaseReference",v.id);}
 for(const auto&r:s.establishments.rows()){const auto&v=r.second;if(v.schedule_commitment_id.empty()||v.occurrence_ordinal<0||v.original_obligation_ref.owner_domain!="local_economy")fail("InvalidAidEstablishment",v.id);take(validate_obligation_ref_shape(v.original_obligation_ref));take(encode_world_moment(v.established_at));strings(v.converted_reservation_refs);}
 for(const auto&r:s.obligations.rows()){const auto&v=r.second;if(v.schedule_commitment_id.empty()||v.occurrence.treaty_id.empty()||v.occurrence.terms_revision<1||v.occurrence.term_id.empty()||v.occurrence.ordinal<0||v.due_tick<0||v.delivery_deadline_tick<v.due_tick||v.beneficiary.id.empty()||!valid_source_ref(v.delivery_site))fail("InvalidMaterialAidObligation",v.id);switch(v.state){case MaterialAidObligationState::owed:case MaterialAidObligationState::partly_received:case MaterialAidObligationState::received:case MaterialAidObligationState::late:case MaterialAidObligationState::settling:case MaterialAidObligationState::closed:break;default:fail("InvalidMaterialAidObligationState",v.id);}switch(v.beneficiary.kind){case SubjectKind::actor:case SubjectKind::organization:case SubjectKind::cohort:break;default:fail("InvalidMaterialAidBeneficiary",v.id);}take(encode_world_moment(v.established_at));source_shape(v.resource_acceptance_ref);strings(v.issue_result_refs);strings(v.receipt_result_refs);if(bool(v.original_money_obligation_id)!=bool(v.frozen_money)||bool(v.original_money_arrear_id)!=bool(v.frozen_money)||(v.original_money_obligation_id&&v.original_money_obligation_id->empty())||(v.original_money_arrear_id&&v.original_money_arrear_id->empty()))fail("MaterialAidOriginalMoneyPayableCoverageMismatch",v.id);if(v.deadline_result_ref&&v.deadline_result_ref->empty())fail("InvalidMaterialAidDeadlineReference",v.id);if(v.frozen_items.empty()&&!v.frozen_money)fail("MaterialAidAmountsRequired",v.id);for(std::size_t i=0;i<v.frozen_items.size();++i){const auto&a=v.frozen_items[i];if(a.item_id.empty()||a.quantity<=0||(i&&v.frozen_items[i-1].item_id>=a.item_id))fail("MaterialAidNormalizedItemsRequired",v.id);}if(v.frozen_money&&(v.frozen_money->currency_id!="qian"||v.frozen_money->amount<=0))fail("MaterialAidMoneyShapeMismatch",v.id);}
 for(const auto&r:s.resource_issues.rows()){if(r.second.obligation_id.empty())fail("MaterialAidIssueObligationRequired",r.first);leg_shape(r.second.actual_issue_ref);take(encode_world_moment(r.second.occurred_at));}
 for(const auto&r:s.receipts.rows()){if(r.second.obligation_id.empty()||r.second.issue_result_id.empty())fail("MaterialAidReceiptIssueRequired",r.first);leg_shape(r.second.actual_receipt_ref);take(encode_world_moment(r.second.occurred_at));}
 for(const auto&r:s.schedule_releases.rows()){if(r.second.schedule_commitment_id.empty())fail("MaterialAidReleaseCommitmentRequired",r.first);source_shape(r.second.actual_termination_ref);take(encode_world_moment(r.second.occurred_at));strings(r.second.released_reservation_refs);}
 for(const auto&r:s.deadline_results.rows()){if(r.second.obligation_id.empty())fail("MaterialAidDeadlineObligationRequired",r.first);take(encode_world_moment(r.second.occurred_at));if(r.second.compensation_obligation_ref)take(validate_obligation_ref_shape(*r.second.compensation_obligation_ref));}
 return common_success();
}catch(Failure&e){return {false,{},std::move(e.error)};}}
Outcome<TreatyMaterialAidState>decode_treaty_material_aid(const BoundaryValue&input){try{TreatyMaterialAidState out;material_aid_codec::decode(input,out,"/treaty_material_aid");const auto valid=validate_treaty_material_aid_shape(out);if(!valid.ok)return {false,{},valid.error};return {true,std::move(out),{}};}catch(const boundary::DecodeFailure&e){return {false,{},e.error};}catch(const exact_fields::CodecFailure&e){return {false,{},e.error};}}
Status emit_treaty_material_aid_projection(ProjectionWriter&w,const StableId&name,const TreatyMaterialAidState&s){auto valid=validate_treaty_material_aid_shape(s);if(!valid.ok)return w.reject(valid.error.original.code,valid.error.original.path);try{return material_aid_codec::emit(w,name,s);}catch(const exact_fields::CodecFailure&e){return {false,{},e.error};}}
Outcome<BoundaryValue>encode_treaty_material_aid(const TreatyMaterialAidState&s){BoundaryValue out;BoundaryProjectionWriter writer(out);auto status=emit_treaty_material_aid_projection(writer,"",s);if(status.ok)status=writer.finish();if(!status.ok)return {false,{},status.error};return {true,std::move(out),{}};}
Status visit_treaty_material_aid_checkpoint(CodecVisitor&c,TreatyMaterialAidState&s){try{if(!c.reading()){const auto valid=validate_treaty_material_aid_shape(s);if(!valid.ok)return c.reject(valid.error.original.code,valid.error.original.path);}const auto result=material_aid_codec::checkpoint(c,"treaty_material_aid",s);if(!result.ok)return result;const auto valid=validate_treaty_material_aid_shape(s);if(!valid.ok)return c.reject(valid.error.original.code,valid.error.original.path);return c.status();}catch(const exact_fields::CodecFailure&e){return {false,{},e.error};}}
Status emit_material_aid_original_fact_payload(ProjectionWriter&w,const StableId&name,const CommonStore&c,const TreatyMaterialAidState&s,const FactRecord&header){const auto*actual=c.state().facts.find(header.id);if(s.schema_version!=1||!actual||actual->domain!=header.domain||actual->kind!=header.kind||header.domain!="local_economy")return w.reject("MaterialAidOriginalHeaderRequired",header.id);
 auto emit=[&](const auto&table){const auto*row=table.find(header.id);if(!row||row->id!=header.id)return w.reject("MaterialAidOriginalPayloadRequired",header.id);return material_aid_codec::emit(w,name,*row);};
 try{if(header.kind=="aid_schedule_accepted")return emit(s.schedule_commitments);if(header.kind=="material_aid_established")return emit(s.establishments);if(header.kind=="material_aid_resources_issued")return emit(s.resource_issues);if(header.kind=="material_aid_received")return emit(s.receipts);if(header.kind=="aid_future_holds_released")return emit(s.schedule_releases);if(header.kind=="material_aid_late")return emit(s.deadline_results);return w.reject("UnsupportedMaterialAidSource",header.id);}catch(const exact_fields::CodecFailure&e){return {false,{},e.error};}}
}
